"""Canonical G-Map manuscript shared by web and PDF; source values unchanged."""
from pathlib import Path
import json
ROOT=Path(__file__).resolve().parents[1]
BASE=ROOT/'content/gmap'
D=json.loads((BASE/'data.js').read_text().split('=',1)[1].strip().rstrip(';'))
EDITION='2026-10-20-gmap-publication-v3'
PDF_NAME='GOSD-2026-section-2-7.pdf'
PDF_RELEASE_NAME='GOSD-2026-section-2-7-20261020-v3.pdf'
TITLE='全球开源治理与社会公益地图（G-Map）'
INTRO='前六节观察了参与、贡献、影响力、人才、资产与协作关系。本节进一步关注共同创造如何延续。基金会为跨组织协作提供承载，许可证为成果共享提供规则。通过组织与许可实践的变化，观察开放生态走向长期维护和持续复用的基础。'
QUESTION='怎样让共同创造的成果，在清晰规则下得到持续维护与复用？'
POSITION='对应 OSDGs 的 X4“开源善治与公共价值”，以基金会项目规模与 OpenRank 占比观察组织承载，以主流许可证和木兰宽松许可证的采用观察共享规则的实践。'
FINDING='基金会项目规模在前期相对稳定后扩大，影响份额连续提升；所列五种许可证的采用数量均增长，MIT 与 Apache-2.0 保持领先；木兰宽松许可证的采用范围与项目影响力同步扩大。共同的行动方向是把组织支持和规则建设落实到长期维护与实际复用。'
WINDOW='除特别说明外，2026 报告年度为 2025 年 7 月 1 日至 2026 年 6 月 30 日；历史年份采用对应的跨年统计期。'
FIGURES=[('foundation','FOUNDATIONS','基金会项目规模与影响份额',[], '2022—2026 报告年度','左轴：活跃仓库；右轴：项目 OpenRank 占比。'),('licenses','LICENSES','活跃仓库 Top 5 许可证趋势',[], '2022—2026 报告年度','五种许可证分别计量，不计算全局许可覆盖率。'),('mulan','MULAN LICENSE','木兰宽松许可证的采用与影响力',[], '2022—2026 报告年度','累计活跃仓库与项目 OpenRank 分别计量。')]
STORIES=[('2.7.1 组织承载：规模相对稳定，影响份额持续提升', ['基金会项目的规模与相对影响，是否沿着同一轨迹变化？图 2-7-1 显示，2022—2025 年活跃仓库保持在 3,163—3,193 个之间，2026 年增至 3,350 个；项目 OpenRank 占比则连续提高，由 2.63% 升至 2.93%。', '规模变化较为平缓，影响份额的提升更为持续。五年间，活跃仓库增加 187 个，增长约 5.9%；OpenRank 占比增加 0.30 个百分点。数量有助于观察组织承载的范围，份额反映相应项目在整体影响力中的位置。对基金会建设而言，扩大项目范围之外，还应重视已有项目的维护、跨组织协作和人员接续，使组织支持能够延续为稳定服务。']), ('2.7.2 共享规则：采用普遍增长，结构有所变化', ['哪些许可证被更多项目采用，五年间的位置如何变化？图 2-7-2 显示，2026 年 MIT 与 Apache-2.0 分别对应 71,760 和 47,820 个活跃仓库，保持前两位；BSD-3-Clause、GPL-3.0 和 AGPL-3.0 分别为 20,910、17,240 和 6,710 个。', '共同增长之中，许可证的相对位置也在变化。2022—2026 年，MIT 与 Apache-2.0 分别增长约 24.2% 和 26.7%；BSD-3-Clause 从略低于 GPL-3.0 转为高于后者。采用规模帮助了解现有实践，具体选择仍应结合项目用途、依赖关系和发布方式。清晰的许可声明与随版本维护的依赖记录，能够帮助使用者判断成果如何复用、需要履行哪些条件。']), ('2.7.3 本土实践：采用范围与项目影响力共同扩大', ['木兰宽松许可证的采用扩大，是否伴随着项目影响力的增长？图 2-7-3 显示，2022—2026 年累计活跃仓库由 27 个增至 391 个，约为期初的 14.5 倍；相关项目 OpenRank 由 689 增至 2,580，约为期初的 3.7 倍。', '采用范围和项目影响力均扩大，但增长节奏不同。仓库数量在 2023 年明显增加，此后持续扩展；项目 OpenRank 也逐年提高。期初基数较小，倍数变化应与绝对规模一起阅读。下一步可沿着真实采用项目，观察持续维护、下游复用和使用反馈，以实践改进应用指南、兼容性说明与工具支持，让许可采用更容易延续为长期使用。'])]
ACTION_TITLE='2.7.4 行动建议：让组织与规则支撑长期共建'
STRATEGIES=[('公共部门与基金会：把长期维护纳入支持安排', ['围绕关键公共技术，将安全修复、文档、人员接续和退出交接纳入资助与项目管理。明确责任人和支持期限，公开运行记录；既关注纳入了多少项目，也持续观察项目是否得到维护、关键职责能否平稳交接。']), ('企业与项目社区：把许可管理嵌入发布流程', ['在项目早期说明许可证、依赖来源、权利归属和贡献规则，随版本更新相关记录，并在发布前完成检查。重点降低下游识别使用条件的成本，让开发者能够找到清晰声明、对应版本及问题反馈入口。']), ('许可证与服务机构：用采用实践改进支持工具', ['围绕主流许可证及木兰系列许可证，完善应用指南、兼容性说明、机器识别和常见问题案例。与真实采用项目建立反馈渠道，优先解决反复出现的理解与使用困难，以材料可用性和问题解决情况检验服务效果。'])]
NOTES=['三组序列沿用报告编制组原表，观察范围不同，不跨图相加。基金会 OpenRank 占比是份额指标，木兰项目 OpenRank 是影响力数值；累计活跃仓库不等同于当年新增仓库。', '基金会样本、份额分母和多许可证统计规则随数据说明完善。现有数量趋势用于观察组织与许可实践，不据此判断治理效率、许可证优劣或社会公益成效，也不推算全局许可覆盖率。']
BRIDGE='第二章从参与基础出发，以组织与共享规则收束：持续共同创造需要参与者、协作关系、开放资产，也需要维护责任和可执行的使用条件。第三章将进一步聚焦项目、组织与贡献者，观察哪些主体形成了持续影响。'
ACTION_INTRO='三组观察指向同一项工作：让组织支持、许可管理和使用服务进入项目的日常协作，保障开放成果持续可用。'
def manuscript():
 out=['# 2.7 '+TITLE,INTRO,'研究问题：'+QUESTION,'指标定位：'+POSITION,'核心发现：'+FINDING,WINDOW]
 for i,(title,ps) in enumerate(STORIES,1):out+=['## '+title,ps[0],f'图 2-7-{i} '+FIGURES[i-1][2],ps[1]]
 out+=['## '+ACTION_TITLE,ACTION_INTRO]
 for title,ps in STRATEGIES:out+=['### '+title,*ps]
 return '\n\n'.join(out+['## 统计范围与指标说明',*NOTES,BRIDGE])+'\n'
